function u(t){return t>=39?9:t>=37?8.5:t>=35?8:t>=33?7.5:t>=30?7:t>=27?6.5:t>=23?6:t>=20?5.5:t>=16?5:t>=13?4.5:t>=10?4:t>=8?3.5:t>=6?3:2.5}function s(t,r){if(t.type==="fill-blank"){const e=Array.isArray(t.answer)?t.answer:[t.answer],i=r.trim().toLowerCase();return e.some(n=>i===String(n).trim().toLowerCase())}if(t.type==="map-label")return r.trim().toUpperCase()===String(t.answer).trim().toUpperCase();if(t.type==="multi-select"&&Array.isArray(t.answer)){const e=new Set(r.split(",").filter(Boolean).map(n=>Number(n))),i=new Set(t.answer);return e.size===i.size&&[...i].every(n=>e.has(n))}return r===String(t.answer)}function f(t,r){if(t.type!=="multi-select"||!Array.isArray(t.answer))return s(t,r)?1:0;const e=new Set(r.split(",").filter(Boolean).map(a=>Number(a))),i=new Set(t.answer);let n=0;for(const a of e)i.has(a)&&n++;return n}function o(t){const r=Math.floor(t/60),e=t%60;return`${String(r).padStart(2,"0")}:${String(e).padStart(2,"0")}`}export{u as bandScore,o as formatCountdown,s as isCorrect,f as multiSelectScore};
